\begin{remark}
	It is apparent from \eqref{OCP} that we minimize the accumulation of ${F(x_k)}$ and ${u_k^ \mathrm {T} R{u_k}}$. The optimal solution $u_t$ is in charge of regulating $x_{t+1}$ to minimize $\sum_{k=t+1}^N[F(x_k)+\frac{1}{2}u_k^TRu_k]+F(x_{N+1})$.
This means that we aim to control $x_k$ to reach the minimum point of $F(x)$ as quickly as possible while avoiding excessive costs associated with large controls. The purpose of transforming problem \eqref{P2} into problem \eqref{OCP} is to theoretically derive the fastest and stable algorithm with the form of \eqref{ztfc}.
\end{remark}


\section{DISTRIBUTED OPTIMIZATION METHOD VIA OPTIMAL CONTROL}\label{s3}
In this section, we use optimal control theory to solve problem \eqref{OCP}. This inspires us to develop an optimization algorithm that can be implemented in a distributed manner. Additionally, a variant of the algorithm is also proposed to balance the number of iterations and communication.
\subsection{Algorithm Development}
Following from \cite{naidu2018optimal}, applying Pontryagin’s maximum principle to problem \eqref{OCP} to yield the following costate equations:
\begin{align}
	&p_{k-1} = p_k + \nabla F(x_k), \label{backward} \\
	&0 = R u_k + p_k, \label{equil}
\end{align} with the terminal condition $p_N=\nabla F(x_{N+1})$. 
From the FBDEs \eqref{ztfc}, \eqref{backward}, \eqref{equil}, we can derive the relationship between the optimal control law \( u_k \) and the optimal state trajectory \( x_k \):
	\begin{align}
		u_k=&-R^{-1}\sum_{t=k+1}^{N+1}\nabla F(x_t),  \label{conlaw}\\
		x_{k+1}=&x_k-R^{-1}\sum_{t=k+1}^{N+1}\nabla F(x_t).\label{iteration relation}
	\end{align}
%\begin{proof}
%See \cite{xu2023optimization} for further details.
%\end{proof}
Noted that \eqref{iteration relation} does not apply to solving the optimal state directly due to its noncausality.
However, the special nonlinear form of \eqref{iteration relation} can be implemented by solving for $(x_k, u_k, p_k)$ such that the FBDEs \eqref{ztfc}, \eqref{backward}, \eqref{equil} are satisfied with the aid of the method of successive approximations (MSA) \cite{xu2023optimization}.
A straightforward algorithm will be presented in this subsection to simplify the calculation.
% \end{align}where $\nabla^2 h(x)$ is the block diagonal matrix with the $i$th diagonal block $\nabla^2f_i(x^i)$.
We define the first-order Taylor expansion of \eqref{conlaw} at $x_{t-1}$ as
\begin{align}
g_k\triangleq-R^{-1}\sum_{t=k+1}^{N+1}\big[\nabla h(x_{t-1})+\nabla^2 h(x_{t-1})(x_t-x_{t-1})+\frac{1}{\lambda}(I-Z)x_t\big],\label{tl}
\end{align}where $\nabla^2 h(x)$ is the block diagonal matrix with the $i$th diagonal block $\nabla^2f_i(x^i)$. Then, an approximate recursion for \eqref{iteration relation} is provided in Lemma \ref{Lm2}.
\begin{lemma}\label{Lm2}
	Dynamics \eqref{iteration relation}  is approximated by the following dynamics
	\begin{align}
		x_{k+1}=&x_{k}+g_k, \label{rimpite}\\
		g_k=-&\big[R+\nabla^2 h(x_k)+\frac{1}{\lambda}(I-Z)\big]^{-1}\big[\nabla h(x_k)+\frac{1}{\lambda}(I-Z)x_k\nonumber\\
		&+\sum_{t=k+1}^{N}(\nabla h(x_{t})+\frac{1}{\lambda}(I-Z)x_{t}-(\nabla^2h(x_{t})+\frac{1}{\lambda}(I-Z))g_{t})\big], \\ 
		g_N=-&\big[R+\nabla^2 h(x_N)+\frac{1}{\lambda}(I-Z)\big]^{-1}\big[{\nabla h(x_N)+\frac{1}{\lambda}(I-Z)x_N}\big].\label{gk}
	\end{align}
\end{lemma}
